-- Тестовые данные. Бренды и товары вымышленные (учебный проект).

insert into public.settings (id, free_delivery_threshold, delivery_fee)
values (true, 12000, 1000)
on conflict (id) do update set free_delivery_threshold = excluded.free_delivery_threshold, delivery_fee = excluded.delivery_fee;

insert into public.brands (name) values
  ('Пушистик'), ('Мурчалка'), ('Дружок'), ('Хвостик'), ('Лапа'), ('Степной вкус')
on conflict (name) do nothing;

