from (values
  ('Сухой корм для котят с курицей', 'Пушистик', 'cat', 'baby', null, 'dry', '1,5 кг', 6800, 8000, 25, 'Полнорационный корм для котят от 2 до 12 месяцев. Мелкие гранулы удобно разгрызать.', 'Курица 32%, рис, кукуруза, рыбий жир, витамины и минералы.', 95),
